const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>new Intl.NumberFormat('id-ID',{style:'currency',currency:'IDR',maximumFractionDigits:0}).format(n);
const when=v=>v?new Intl.DateTimeFormat('id-ID',{dateStyle:'medium',timeStyle:'short',timeZone:'Asia/Jakarta'}).format(new Date(v)):'Belum';
let data={invitations:[],responses:[],gifts:[],giftActivity:[],readingProgress:[],events:[],content:null},page='guests',editId=null,detailId=null,slugEdited=false,toastTimer,deleteId=null;
async function api(path,{method='GET',body}={}){const r=await fetch('/api/admin/'+path,{method,headers:body?{'Content-Type':'application/json'}:{},...(body?{body:JSON.stringify(body)}:{})});let result;try{result=await r.json();}catch{throw new Error('Respons server tidak dapat dibaca. Coba lagi.');}if(!r.ok){if(r.status===401)location.href='/admin';throw new Error(result.error||'Tidak dapat menyimpan data.');}return result;}
function toast(message){$('#toast').textContent=message;$('#toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').hidden=true,4500);}
function topError(error){$('#app-error').textContent=error.message;$('#app-error').hidden=false;}
function badge(text,kind=''){return `<span class="pill ${kind}">${esc(text)}</span>`;}
function responseFor(inv,eventId){if(!inv.eventIds.includes(eventId))return null;return data.responses.find(r=>r.invitation_id===inv.id&&r.event_id===eventId)||{status:'pending',guest_count:0};}
const RSVP_LABEL={pending:'Belum menjawab',attending:'Akan hadir',declined:'Tidak hadir'};
const displayName=i=>window.weddingDisplayName(i,'id');
const TABLE_GROUPS={Galilea:5,Jordan:10,Pishon:10},TABLE_CAPACITY=10;
const tableLabel=value=>value?value.replace('-', ' · Meja '):'Belum ditentukan';
function rsvpMarkup(r){return r?badge(RSVP_LABEL[r.status]+(r.status==='attending'?` · ${r.guest_count} tamu`:''),r.status==='attending'?'good':r.status==='declined'?'bad':'warm'):badge('Tidak diundang');}
const READING_LABELS=['Pembuka','01 · Undangan','02 · Mempelai','03 · Momen kami','04 · Detail acara','05 · Konfirmasi kehadiran','06 · Buku pesan','Penutup'];
const readingFor=id=>(data.readingProgress||[]).find(r=>r.invitation_id===id);
const readingLabel=r=>r?`${Number(r.max_depth)||0}% · sampai ${READING_LABELS[r.deepest_section]}`:'Belum ada data scroll';
const activityFor=id=>(data.giftActivity||[]).find(a=>a.invitation_id===id)||{};
const activitySummary=a=>`${Number(a.opened)||0} klik hadiah · ${Number(a.copy_clicked)||0} klik salin · ${Number(a.account_copied)||0} salin berhasil`;
function renderGuests(){
 const eventId=$('#event-filter').value||'all',allEvents=eventId==='all';
 const {active,visible:filtered,opened,attending,attendingInvitations,invitedGuests,pendingGuests,pendingInvitations}=window.weddingGuestList({...data,eventId,search:$('#search').value,status:$('#status-filter').value});
 const eventLabel=allEvents?'Semua acara':data.events.find(e=>e.id===eventId)?.title||'acara terpilih';
 $('#stat-invitations').textContent=active.length;$('#stat-invitation-event').textContent=eventLabel;$('#stat-opened').textContent=opened;$('#stat-unopened').textContent=`${active.length-opened} belum dibuka`;$('#stat-attending').textContent=attending;$('#stat-event').textContent=`${attendingInvitations} undangan mengonfirmasi hadir`;$('#stat-gifts').textContent=data.gifts.filter(g=>g.status==='confirmed').length;
 $('#stat-invited-guests').textContent=invitedGuests;$('#stat-pending-guests').textContent=pendingGuests;$('#stat-pending-invitations').textContent=`${pendingInvitations} undangan belum menjawab`;
 $('#guest-count-note').textContent=`Hitungan undangan personal aktif · ${eventLabel}. Jumlah diundang mengikuti tamu maksimal di CMS; jumlah hadir mengikuti RSVP.${allEvents?' Untuk semua acara, satu undangan dihitung sekali dengan jumlah hadir terbanyak di antara acara.':''} RSVP undangan umum tersedia di menu tersendiri. Undangan yang menolak semua acara dipindah dari daftar utama ke menu Arsip Tidak Hadir. Pencarian dan filter status hanya menyaring daftar di bawah.`;
 $('#event-guest-counts').innerHTML=data.events.filter(e=>allEvents||e.id===eventId).map(e=>{const c=window.weddingGuestList({...data,eventId:e.id});return `<tr><td><strong>${esc(e.title)}</strong><small>${c.active.length} undangan aktif</small></td><td>${c.invitedGuests} orang</td><td>${c.attending} orang<small>${c.attendingInvitations} undangan</small></td><td>${c.pendingGuests} orang<small>${c.pendingInvitations} undangan</small></td><td>${c.declinedGuests} orang<small>${c.declinedInvitations} undangan</small></td></tr>`;}).join('');
 $('#guest-rows').innerHTML=filtered.length?filtered.map(i=>{const gifts=data.gifts.filter(g=>g.invitation_id===i.id&&g.status!=='cancelled');const rsvp=allEvents?data.events.filter(e=>i.eventIds.includes(e.id)).map(e=>`<div><small>${esc(e.title)}</small>${rsvpMarkup(responseFor(i,e.id))}</div>`).join(''):rsvpMarkup(responseFor(i,eventId));return `<tr><td><label class="bulk-select"><input type="checkbox" data-bulk-rsvp-select="${i.id}" aria-label="Pilih ${esc(displayName(i))}" ${!i.active?'disabled':''}></label></td><td><strong>${esc(displayName(i))}</strong><small>/${esc(i.slug)} · maks. ${i.seats} tamu${i.active?'':' · nonaktif'}</small>${i.eventIds.includes('reception')&&(allEvents||eventId==='reception')?`<small>${window.weddingSeating.isDeclined(i,'reception',data.responses)?'Arsip · tidak mengisi meja':esc(tableLabel(i.receptionTable))}</small>`:''}<small>♡ ${i.heartCount||0} hati${i.lastHeartAt?' · terakhir '+esc(when(i.lastHeartAt)):''}</small></td><td>${badge(i.firstOpenedAt?'Sudah dibuka':'Belum dibuka',i.firstOpenedAt?'good':'')}<small>${i.firstOpenedAt?esc(when(i.firstOpenedAt)):i.sharedAt?'Link disalin '+esc(when(i.sharedAt)):'Link belum disalin'}</small><small>${esc(readingLabel(readingFor(i.id)))}</small></td><td>${rsvp}</td><td>${gifts.length?badge(gifts.some(g=>g.status==='reported')?'Perlu verifikasi':`${gifts.length} diterima`,gifts.some(g=>g.status==='reported')?'warm':'good'):'—'}<small>${esc(activitySummary(activityFor(i.id)))}</small></td><td><div class="row-actions"><button class="quiet" data-action="detail" data-id="${i.id}">Detail</button><button class="quiet" data-action="rsvp" data-id="${i.id}" data-event-id="${allEvents?'':eventId}" ${!i.active?'disabled':''}>Konfirmasi</button><button class="quiet" data-action="copy" data-id="${i.id}" ${!i.active?'disabled':''}>Salin link</button><button class="quiet danger" data-action="delete" data-id="${i.id}" aria-label="Hapus undangan ${esc(displayName(i))}">Hapus</button></div></td></tr>`;}).join(''):'<tr><td colspan="6" class="empty"><strong>Tidak ada undangan yang cocok dengan filter ini.</strong>Pilih “Semua acara” atau hapus filter untuk melihat daftar lengkap.</td></tr>';
 $('#result-count').textContent=`${filtered.length} dari ${data.invitations.length} undangan ditampilkan · ${eventLabel}`;
}
function showAllGuests(active=true){$('#event-filter').value='all';$('#status-filter').value=active?'all':'inactive';$('#search').value='';}
function reservedAt(table,exceptId=null){return window.weddingSeating.reservedAt(data.invitations,data.responses,table,exceptId);}
function renderTables(){
 const isDeclined=i=>window.weddingSeating.isDeclined(i,'reception',data.responses);
 const archived=data.invitations.filter(i=>i.active&&isDeclined(i));
 const assigned=data.invitations.filter(i=>i.active&&i.eventIds.includes('reception')&&i.receptionTable&&!isDeclined(i));
 const pending=data.invitations.filter(i=>i.active&&i.eventIds.includes('reception')&&!i.receptionTable&&!isDeclined(i));
 const full=Object.entries(TABLE_GROUPS).flatMap(([group,total])=>Array.from({length:total},(_,index)=>`${group}-${index+1}`)).filter(table=>reservedAt(table)>=TABLE_CAPACITY).length;
 $('#table-summary').textContent=`${assigned.length} undangan mendapat meja · ${pending.length} belum mendapat meja · ${archived.length} arsip RSVP tidak hadir · ${full} dari 25 meja penuh · maksimal 10 kursi per meja. Tamu tidak hadir tidak memakan kursi.`;
 $('#table-groups').innerHTML=Object.entries(TABLE_GROUPS).map(([group,total])=>`<section class="table-group"><h2>${group} <small>${total} meja</small></h2><div class="table-card-grid">${Array.from({length:total},(_,index)=>{const number=index+1,key=`${group}-${number}`,guests=assigned.filter(i=>i.receptionTable===key),reserved=reservedAt(key);const attending=guests.reduce((sum,i)=>sum+(responseFor(i,'reception')?.status==='attending'?responseFor(i,'reception').guest_count:0),0);return `<article class="table-card ${reserved>=TABLE_CAPACITY?'table-full':reserved>=8?'table-near-full':''}"><h3>Meja ${number}</h3><p><strong>${reserved}/${TABLE_CAPACITY} kursi dialokasikan</strong> · ${attending} konfirmasi hadir</p><span class="table-state">${reserved>=TABLE_CAPACITY?'Meja penuh':`Tersisa ${TABLE_CAPACITY-reserved} kursi`}</span>${guests.length?`<ul>${guests.map(i=>`<li><button type="button" class="table-guest" data-table-guest="${i.id}">${esc(displayName(i))}</button> <small>maks. ${i.seats}</small></li>`).join('')}</ul>`:'<span class="table-empty">Belum ada tamu</span>'}</article>`;}).join('')}</div></section>`).join('')+`<section class="table-group"><h2>Belum ditentukan</h2>${pending.length?`<ul>${pending.map(i=>`<li><button type="button" class="table-guest" data-table-guest="${i.id}">${esc(displayName(i))}</button> · maks. ${i.seats} tamu</li>`).join('')}</ul>`:'<p>Semua undangan Resepsi I yang masih aktif untuk seating sudah mendapat meja.</p>'}</section>`;
}
function renderArchive(){
 const selector=$('#archive-event'),selected=selector.value||'all';
 selector.innerHTML='<option value="all">Semua acara</option>'+data.events.map(e=>`<option value="${esc(e.id)}">${esc(e.title)}</option>`).join('');
 if(selected==='all'||data.events.some(e=>e.id===selected))selector.value=selected;
 const entries=window.weddingSeating.archiveEntries(data,selector.value),term=$('#archive-search').value.toLocaleLowerCase('id-ID').trim();
 const filtered=entries.filter(({inv,event})=>!term||`${inv.guestName} ${inv.slug} ${event?.title||''}`.toLocaleLowerCase('id-ID').includes(term));
 $('#archive-summary').textContent=`${entries.length} konfirmasi tidak hadir tersimpan · ${filtered.length} ditampilkan. Arsip mengikuti jawaban RSVP terbaru, tanpa menghapus undangan, dan kursi Resepsi I otomatis bebas untuk alokasi lain.`;
 $('#archive-rows').innerHTML=filtered.length?filtered.map(({inv,event,response})=>`<tr><td><label class="bulk-select"><input type="checkbox" data-bulk-rsvp-select="${inv.id}" aria-label="Pilih ${esc(displayName(inv))}"></label></td><td><strong>${esc(displayName(inv))}</strong><small>/${esc(inv.slug)}</small></td><td>${esc(event?.title||response.event_id)}</td><td>${badge('Tidak hadir','bad')}<small>${esc(when(response.updated_at))}</small></td><td>${response.event_id==='reception'?'<small>Alokasi aktif: 0 kursi</small>':''}<small>Kuota undangan: ${inv.seats} orang</small></td><td><button class="quiet" data-action="detail" data-id="${inv.id}">Detail</button><button class="quiet" data-action="rsvp" data-id="${inv.id}" data-event-id="${response.event_id}">Konfirmasi</button></td></tr>`).join(''):'<tr><td colspan="6" class="empty">Tidak ada RSVP tidak hadir yang cocok.</td></tr>';
}

$('#table-groups').addEventListener('click',event=>{const id=event.target.closest('[data-table-guest]')?.dataset.tableGuest;if(id)showDetail(id);});
function renderGifts(){const status=$('#gift-filter').value;const gifts=data.gifts.filter(g=>status==='all'||g.status===status);const confirmed=data.gifts.filter(g=>g.status==='confirmed'),reported=data.gifts.filter(g=>g.status==='reported');$('#gift-summary').textContent=`${confirmed.length} diterima · ${reported.length} perlu verifikasi · Nominal terverifikasi ${money(confirmed.reduce((sum,g)=>sum+(g.amount||0),0))}`;
 const kinds={transfer:'Transfer',cash:'Amplop / tunai',goods:'Barang',other:'Lainnya'};
 $('#gift-rows').innerHTML=gifts.length?gifts.map(g=>{const inv=data.invitations.find(i=>i.id===g.invitation_id);return `<tr><td><strong>${esc(inv?.guestName||'Tamu')}</strong><small>${esc(when(g.created_at))}</small></td><td>${esc(kinds[g.kind])}<small>${g.amount===null?'Nominal tidak diisi':esc(money(g.amount))}</small></td><td>${esc(g.note)||'—'}<small>Dicatat oleh ${g.source==='guest'?'tamu':'admin'}</small>${g.proof_key?`<a href="/api/admin/gifts/${encodeURIComponent(g.id)}/proof" target="_blank" rel="noopener noreferrer">Lihat bukti transfer ↗</a>`:''}</td><td>${badge(g.status==='confirmed'?'Diterima':g.status==='reported'?'Perlu verifikasi':'Dibatalkan',g.status==='confirmed'?'good':g.status==='reported'?'warm':'')}<small>${g.verified_at?esc(when(g.verified_at)):''}</small></td><td><div class="row-actions">${g.status!=='confirmed'?`<button class="quiet" data-action="gift-status" data-id="${g.id}" data-status="confirmed">Tandai diterima</button>`:`<button class="quiet" data-action="gift-status" data-id="${g.id}" data-status="reported">Periksa ulang</button>`}${g.status!=='cancelled'?`<button class="quiet" data-action="gift-status" data-id="${g.id}" data-status="cancelled">Batalkan catatan</button>`:''}</div></td></tr>`;}).join(''):'<tr><td colspan="5" class="empty"><strong>Belum ada catatan hadiah.</strong>Konfirmasi tamu dan catatan manual akan tampil di sini.</td></tr>';
}
function renderEvents(){const input=(label,name,value,type='text')=>`<label>${label}<input name="${name}" value="${esc(value||'')}" type="${type}" ${name.endsWith('title')||name.endsWith('titleEn')||name.endsWith('date')||name.endsWith('venue')?'required':''}></label>`;
 $('#event-editors').innerHTML=data.events.map(e=>`<article class="event-editor" data-event-id="${e.id}"><h2>${esc(e.title)}</h2><div class="form-columns">${input('Nama acara · Bahasa Indonesia',e.id+'-title',e.title)}${input('Event name · English',e.id+'-titleEn',e.titleEn)}</div><div class="form-columns">${input('Tanggal',e.id+'-date',e.date,'date')}${input('Jam mulai (WIB)',e.id+'-start',e.start?.slice(11,16),'time')}${input('Jam selesai (opsional)',e.id+'-end',e.end?.slice(11,16),'time')}</div>${input('Nama tempat',e.id+'-venue',e.venue)}${input('Alamat / kota',e.id+'-address',e.address)}${input('Link Google Maps (opsional)',e.id+'-mapsUrl',e.mapsUrl,'url')}</article>`).join('');
}
async function refresh(){const [next,cms]=await Promise.all([api('invitations'),api('content')]);const defaults=window.WEDDING_CONTENT_DEFAULTS;data={...next,content:cms.content?{...defaults,...cms.content,photos:Array.isArray(cms.content.photos)&&cms.content.photos.length===defaults.photos.length?cms.content.photos:defaults.photos,featured:Array.isArray(cms.content.photos)&&cms.content.photos.length===defaults.photos.length?cms.content.featured:defaults.featured,texts:{...defaults.texts,...cms.content.texts},textsEn:{...window.WEDDING_ENGLISH_TEXTS,...cms.content.textsEn}}:{...structuredClone(defaults),textsEn:{...window.WEDDING_ENGLISH_TEXTS}}};const selected=$('#event-filter').value;$('#event-filter').innerHTML='<option value="all">Semua acara</option>'+data.events.map(e=>`<option value="${e.id}">${esc(e.title)}</option>`).join('');if(selected==='all'||data.events.some(e=>e.id===selected))$('#event-filter').value=selected;window.weddingBulkRsvp.setContext(data,refresh,toast);renderGuests();renderTables();renderArchive();window.weddingBulkRsvp.sync();renderGifts();renderEvents();renderCMS();$('#loading').hidden=true;$('#app-error').hidden=true;showPage(page);}
function showPage(next){page=next;if(next==='journey'||next==='rundown')window.weddingJourney.load(next,{data,api,refresh,toast});if(next==='reading')loadReading(readingPage);if(next==='gifts')loadGiftActivity(giftActivityPage);if(next==='messages')loadMessages(messagesPage);if(next==='general-rsvps')loadGeneralRsvps(generalPage);document.querySelectorAll('.page').forEach(el=>el.hidden=el.id!==next+'-page');document.querySelectorAll('[data-page]').forEach(el=>el.classList.toggle('active',el.dataset.page===next));}
document.querySelectorAll('[data-page]').forEach(button=>button.addEventListener('click',()=>showPage(button.dataset.page)));
$('#archive-event').addEventListener('change',renderArchive);$('#archive-search').addEventListener('input',renderArchive);
for(const name of ['#search','#event-filter','#status-filter'])$(name).addEventListener(name==='#search'?'input':'change',renderGuests);$('#clear-guest-filters').addEventListener('click',()=>{showAllGuests();renderGuests();});$('#gift-filter').addEventListener('change',renderGifts);$('#refresh').addEventListener('click',async e=>{e.currentTarget.disabled=true;try{await refresh();toast('Data diperbarui.');}catch(err){topError(err);}finally{$('#refresh').disabled=false;}});
document.querySelectorAll('[data-close]').forEach(b=>b.addEventListener('click',()=>$('#'+b.dataset.close).close()));
function slugify(value){return value.normalize('NFKD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/^(bapak|ibu|saudara|saudari|pak|bu)\s+/,'').replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'').slice(0,60);}
$('#guest-name-input').addEventListener('input',e=>{if(!editId&&!slugEdited)$('#slug-input').value=slugify(e.target.value);});$('#slug-input').addEventListener('input',()=>slugEdited=true);
function openInvitation(inv=null){editId=inv?.id||null;slugEdited=Boolean(inv);const form=$('#invitation-form');form.reset();$('#invitation-error').textContent='';$('#invitation-title').textContent=inv?'Edit undangan':'Buat undangan';$('#save-invitation').textContent=inv?'Simpan perubahan':'Buat undangan';$('#slug-input').readOnly=Boolean(inv);$('#active-field').hidden=!inv;for(const name of ['guestName','salutation','slug','phone','seats','privateNote'])form.elements[name].value=inv?.[name]??(name==='seats'?2:'');form.elements.active.checked=inv?.active??true;$('#invited-events').innerHTML=data.events.map(e=>`<label class="checkbox-row"><input name="eventIds" type="checkbox" value="${e.id}" ${inv?.eventIds.includes(e.id)?'checked':''}> ${esc(e.title)}</label>`).join('');$('#reception-table').innerHTML='<option value="">Belum ditentukan</option>'+Object.entries(TABLE_GROUPS).map(([group,total])=>`<optgroup label="${group}">${Array.from({length:total},(_,index)=>`<option value="${group}-${index+1}">${group} · Meja ${index+1}</option>`).join('')}</optgroup>`).join('');$('#reception-table').value=inv?.receptionTable||'';updateReceptionTableField();$('#invitation-dialog').showModal();$('#guest-name-input').focus();}
function updateReceptionTableField(){const invited=$('#invited-events [value="reception"]')?.checked;$('#reception-table-field').hidden=!invited;if(!invited)$('#reception-table').value='';updateCapacityWarning();}
function updateCapacityWarning(){const table=$('#reception-table').value,warning=$('#table-capacity-warning');if(!table){warning.textContent='';return;}const remaining=TABLE_CAPACITY-reservedAt(table,editId),requested=Number($('#invitation-form').elements.seats.value)||0;warning.textContent=requested>remaining?`Meja penuh untuk undangan ini. Tersisa ${Math.max(0,remaining)} dari 10 kursi; pilih meja lain atau kurangi kursi.`:`Tersisa ${remaining-requested} dari 10 kursi setelah undangan ini disimpan.`;warning.classList.toggle('over-capacity',requested>remaining);}
$('#reception-table').addEventListener('change',updateCapacityWarning);$('#invitation-form').elements.seats.addEventListener('input',updateCapacityWarning);$('#invitation-form').elements.active.addEventListener('change',updateCapacityWarning);
$('#invited-events').addEventListener('change',updateReceptionTableField);
$('#new-invitation').addEventListener('click',()=>openInvitation());
$('#invitation-form').addEventListener('submit',async e=>{e.preventDefault();const f=e.currentTarget,b=$('#save-invitation');const body={guestName:f.elements.guestName.value,salutation:f.elements.salutation.value,slug:f.elements.slug.value,phone:f.elements.phone.value,seats:Number(f.elements.seats.value),receptionTable:f.elements.receptionTable.value,privateNote:f.elements.privateNote.value,eventIds:[...f.querySelectorAll('[name=eventIds]:checked')].map(i=>i.value),active:f.elements.active.checked};if(!body.eventIds.length){$('#invitation-error').textContent='Pilih setidaknya satu acara untuk undangan ini.';return;}b.disabled=true;$('#invitation-error').textContent='';try{const r=await api(editId?'invitations/'+editId:'invitations',{method:editId?'PATCH':'POST',body});$('#invitation-dialog').close();showAllGuests(r.invitation.active);await refresh();showDetail(r.invitation.id);toast(editId?'Undangan diperbarui.':'Undangan personal berhasil dibuat.');}catch(error){$('#invitation-error').textContent=error.message;}finally{b.disabled=false;}});
async function shareURL(invId){const result=await api('invitations/'+invId+'/link');return new URL(result.sharePath,location.origin).href;}
async function markShared(invId){await api('invitations/'+invId+'/shared',{method:'POST',body:{}});await refresh();}
async function copyLink(invId){const url=await shareURL(invId);try{await navigator.clipboard.writeText(url);}catch{showDetail(invId);const wrap=document.createElement('label');wrap.textContent='Salin tautan lengkap ini';const input=document.createElement('input');input.value=url;input.readOnly=true;wrap.append(input);$('#detail-body').append(wrap);input.select();toast('Pilih dan salin tautan yang ditampilkan.');return;}await markShared(invId);toast('Tautan personal disalin. Bagikan tautan lengkap agar RSVP dan tracking aktif.');}
function showDetail(invId){detailId=invId;const i=data.invitations.find(i=>i.id===invId);if(!i)return;$('#detail-name').textContent=displayName(i);const gifts=data.gifts.filter(g=>g.invitation_id===i.id&&g.status!=='cancelled');$('#detail-body').innerHTML=`<p>/${esc(i.slug)} · maksimal ${i.seats} tamu ${i.active?'':badge('Nonaktif','bad')}</p><div class="detail-stat"><span>Pertama dibuka<small>${esc(when(i.firstOpenedAt))}</small></span><span>${i.openCount} kunjungan tercatat<small>Terakhir: ${esc(when(i.lastOpenedAt))}</small></span></div><div class="detail-stat"><span>Hati dikirim<small>Terakhir: ${esc(when(i.lastHeartAt))}</small></span><strong>${i.heartCount||0} ♡</strong></div><div class="detail-stat"><span>Link disalin / dibagikan</span><span>${esc(when(i.sharedAt))}</span></div>${i.phone?`<div class="detail-stat"><span>WhatsApp</span><span>${esc(i.phone)}</span></div>`:''}${i.eventIds.includes('reception')?`<div class="detail-stat"><span>Meja Resepsi I</span><strong>${window.weddingSeating.isDeclined(i,'reception',data.responses)?'Arsip · tidak mengisi meja':esc(tableLabel(i.receptionTable))}</strong></div>`:''}<h3 class="detail-subtitle">Konfirmasi kehadiran</h3>${data.events.filter(e=>i.eventIds.includes(e.id)).map(e=>{const r=responseFor(i,e.id);return `<div class="detail-stat"><span>${esc(e.title)}${r.updated_at?`<small>${esc(when(r.updated_at))}</small>`:''}</span>${rsvpMarkup(r)}</div>${r.message?`<div class="detail-note">${esc(r.message)}</div>`:''}`;}).join('')}<h3 class="detail-subtitle">Perjalanan undangan</h3><p>${esc(readingLabel(readingFor(i.id)))}</p>${readingFor(i.id)?`<div class="detail-stat"><span>Section terakhir: ${esc(READING_LABELS[readingFor(i.id).last_section])}<small>${esc(when(readingFor(i.id).last_seen))}</small></span><strong>${Number(readingFor(i.id).visits)} kunjungan</strong></div>`:''}<h3 class="detail-subtitle">Aktivitas hadiah</h3><p>${esc(activitySummary(activityFor(i.id)))}</p><p class="data-note">Terakhir: ${esc(when(activityFor(i.id).last_activity_at))}. Klik hadiah atau salin rekening tidak menunjukkan transfer sudah diterima.</p><h3 class="detail-subtitle">Hadiah</h3><p>${gifts.length?`${gifts.length} catatan · ${gifts.filter(g=>g.status==='confirmed').length} sudah diterima`:'Belum ada catatan hadiah.'}</p>${i.privateNote?`<div class="detail-note"><strong>Catatan pribadi</strong><br>${esc(i.privateNote)}</div>`:''}<p class="data-note">Tautan lengkap menyertakan kode akses tamu. Setelah dibuka, alamat menjadi /${esc(i.slug)}. Kode ini menjaga RSVP dan detail hadiah dari perubahan oleh orang yang sekadar menebak nama tautan.</p>`;
 $('#detail-actions').innerHTML=`<button class="secondary" data-action="edit" data-id="${i.id}">Edit</button><button class="primary" data-action="rsvp" data-id="${i.id}" ${!i.active?'disabled':''}>Konfirmasi RSVP</button><button class="secondary" data-action="preview" data-id="${i.id}" ${!i.active?'disabled':''}>Preview ↗</button><button class="secondary" data-action="whatsapp" data-id="${i.id}" ${!i.active?'disabled':''}>WhatsApp ↗</button><button class="primary" data-action="copy" data-id="${i.id}" ${!i.active?'disabled':''}>Salin tautan</button><button class="secondary danger" data-action="delete" data-id="${i.id}">Hapus undangan</button>`;if(!$('#detail-dialog').open)$('#detail-dialog').showModal();}
document.body.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b)return;const {action,id:invId,status}=b.dataset;try{
 if(action==='detail')showDetail(invId);
 if(action==='rsvp'){const inv=data.invitations.find(i=>i.id===invId);await window.weddingAdminRsvp.open(inv,data,async(id,result)=>{await refresh();showDetail(id);toast(result.seatReassignmentRequired?'RSVP tersimpan. Pilih meja baru karena meja sebelumnya sudah dipakai.':'Konfirmasi RSVP tersimpan dan tampilan meja diperbarui.');},b.dataset.eventId||'');}
 if(action==='delete'){const inv=data.invitations.find(i=>i.id===invId);if(!inv)return;deleteId=invId;$('#delete-guest-name').textContent=displayName(inv);$('#delete-guest-slug').textContent='/'+inv.slug;$('#delete-error').textContent='';$('#detail-dialog').close();$('#delete-dialog').showModal();$('#delete-dialog [data-close]').focus();}
 if(action==='edit'){$('#detail-dialog').close();openInvitation(data.invitations.find(i=>i.id===invId));}
 if(action==='copy'){b.disabled=true;await copyLink(invId);}
 if(action==='preview'){const w=window.open('/'+data.invitations.find(i=>i.id===invId).slug,'_blank');if(w)w.opener=null;}
 if(action==='whatsapp'){const i=data.invitations.find(i=>i.id===invId),url=await shareURL(invId);let phone=i.phone.replace(/\D/g,'');if(phone.startsWith('0'))phone='62'+phone.slice(1);const msg=`Yth. ${displayName(i)},\nDengan penuh sukacita, kami mengundang ${displayName(i)} merayakan pernikahan (nama pria) & (nama wanita).\n\nUndangan dan konfirmasi kehadiran:\n${url}\n\nTerima kasih atas doa dan kehadirannya. ♡`;const a=document.createElement('a');a.href='https://wa.me/'+phone+'?text='+encodeURIComponent(msg);a.target='_blank';a.rel='noopener noreferrer';a.click();await markShared(invId);toast('Pesan disiapkan di WhatsApp. Kamu yang memilih dan menekan kirim.');}
 if(action==='gift-status'){b.disabled=true;await api('gifts/'+invId,{method:'PATCH',body:{status}});await refresh();toast('Status hadiah diperbarui.');}
 }catch(error){toast(error.message);}finally{b.disabled=false;}});

$('#delete-form').addEventListener('submit',async event=>{
 event.preventDefault();const inv=data.invitations.find(i=>i.id===deleteId);if(!inv)return;
 const button=$('#confirm-delete');button.disabled=true;$('#delete-error').textContent='';
 try{
  await api('invitations/'+inv.id,{method:'DELETE',body:{slug:inv.slug}});
  $('#delete-dialog').close();deleteId=null;detailId=null;
  data.invitations=data.invitations.filter(i=>i.id!==inv.id);data.responses=data.responses.filter(r=>r.invitation_id!==inv.id);data.gifts=data.gifts.filter(g=>g.invitation_id!==inv.id);data.giftActivity=(data.giftActivity||[]).filter(a=>a.invitation_id!==inv.id);data.readingProgress=(data.readingProgress||[]).filter(r=>r.invitation_id!==inv.id);
  renderGuests();renderTables();renderGifts();toast('Undangan '+displayName(inv)+' dihapus.');
  try{await refresh();}catch(error){topError(error);}
 }catch(error){$('#delete-error').textContent=error.message;}finally{button.disabled=false;}
});
$('#new-gift').addEventListener('click',()=>{if(!data.invitations.length){toast('Buat undangan tamu terlebih dahulu.');return;}const form=$('#gift-form');form.reset();form.dataset.requestId=crypto.randomUUID();$('#gift-error').textContent='';$('#gift-invitation').innerHTML=data.invitations.map(i=>`<option value="${i.id}">${esc(displayName(i))}</option>`).join('');$('#gift-dialog').showModal();});
$('#gift-form').addEventListener('submit',async e=>{e.preventDefault();const f=e.currentTarget,b=f.querySelector('[type=submit]');b.disabled=true;$('#gift-error').textContent='';try{await api('gifts',{method:'POST',body:{invitationId:f.elements.invitationId.value,kind:f.elements.kind.value,amount:f.elements.amount.value===''?null:Number(f.elements.amount.value),note:f.elements.note.value,status:f.elements.status.value,requestId:f.dataset.requestId}});$('#gift-dialog').close();await refresh();toast('Hadiah tercatat.');}catch(error){$('#gift-error').textContent=error.message;}finally{b.disabled=false;}});
$('#events-form').addEventListener('submit',async e=>{e.preventDefault();const form=e.currentTarget,b=form.querySelector('[type=submit]');const value=name=>form.elements[name].value.trim();const events=data.events.map(event=>{const k=event.id,date=value(k+'-date'),start=value(k+'-start'),end=value(k+'-end');return {id:k,title:value(k+'-title'),titleEn:value(k+'-titleEn'),date,start:start?`${date}T${start}:00+07:00`:null,end:end?`${date}T${end}:00+07:00`:null,venue:value(k+'-venue'),address:value(k+'-address'),mapsUrl:value(k+'-mapsUrl')||null};});b.disabled=true;$('#event-error').textContent='';try{await api('events',{method:'PUT',body:{events}});await refresh();toast('Detail acara diperbarui pada semua undangan.');}catch(error){$('#event-error').textContent=error.message;}finally{b.disabled=false;}});
function photoSelect(name,selected){const chosen=data.content.photos.find(p=>p.id===selected);return `<label>${name}<select>${data.content.photos.map(p=>`<option value="${p.id}" ${selected===p.id?'selected':''}>Foto ${String(p.id).padStart(2,'0')} — ${esc(p.caption)}</option>`).join('')}</select><img class="cms-featured-preview" src="${esc(chosen?.src||'')}" alt="${esc(chosen?.alt||'')}" loading="lazy"></label>`;}
function renderCMS(){
 const content=data.content;
 const fields=Object.fromEntries(window.WEDDING_TEXT_FIELDS.map(field=>[field.key,field]));
 $('#cms-text-fields').innerHTML=window.WEDDING_TEXT_SECTIONS.map((section,index)=>`<details class="cms-section" ${index===0?'open':''}><summary><span>${esc(section.title)}</span><small>${section.fields.length} tulisan · <a href="/#${esc(section.anchor)}" target="_blank" rel="noopener">Lihat section ↗</a></small></summary><div class="cms-text-grid">${section.fields.map(([key])=>{const field=fields[key],control=(language,value)=>field.multiline?`<textarea data-${language}-key="${key}" maxlength="600" required>${esc(value)}</textarea>`:`<input data-${language}-key="${key}" value="${esc(value)}" maxlength="600" required>`;return `<div class="cms-bilingual"><label>${esc(field.label)} · Indonesia${control('text',content.texts[key])}</label><label>${esc(field.label)} · English${control('english',content.textsEn[key])}</label></div>`;}).join('')}</div></details>`).join('');
 $('#cms-photo-fields').innerHTML=content.photos.map(p=>`<article class="cms-photo-card" data-photo-id="${p.id}"><img src="${esc(p.src)}" alt="${esc(p.alt)}" loading="lazy"><h2>Foto ${String(p.id).padStart(2,'0')}</h2><label>Ganti foto<input type="file" accept="image/jpeg,image/png,image/webp,image/avif" aria-label="Unggah foto ${p.id}"></label><p class="upload-status" role="status">${p.src.startsWith('/media/')?'Foto unggahan':'Foto awal'}</p><label>Caption · Indonesia<input data-photo-field="caption" value="${esc(p.caption)}" maxlength="120" required></label><label>Caption · English<input data-photo-field="captionEn" value="${esc(p.captionEn||p.caption)}" maxlength="120" required></label><label>Teks alternatif · Indonesia<input data-photo-field="alt" value="${esc(p.alt)}" maxlength="200" required></label><label>Alt text · English<input data-photo-field="altEn" value="${esc(p.altEn||window.WEDDING_ENGLISH_PHOTO_ALTS[p.id])}" maxlength="200" required></label><label>Kategori<select data-photo-field="category"><option value="office" ${p.category==='office'?'selected':''}>The office edit</option><option value="garden" ${p.category==='garden'?'selected':''}>Garden vows</option><option value="casual" ${p.category==='casual'?'selected':''}>Off duty</option></select></label></article>`).join('');
 $('#cms-featured-fields').innerHTML=content.featured.hero.map((v,i)=>photoSelect(`Slide pembuka ${i+1}`,v)).join('')+photoSelect('Foto cerita pasangan',content.featured.couple)+photoSelect('Foto penutup',content.featured.closing);
}
$('#cms-featured-fields').addEventListener('change',e=>{if(e.target.tagName!=='SELECT')return;const photo=data.content.photos.find(p=>p.id===Number(e.target.value)),preview=e.target.parentElement.querySelector('img');if(photo&&preview){preview.src=photo.src;preview.alt=photo.alt;}});
$('#content-form').addEventListener('submit',async e=>{e.preventDefault();const form=e.currentTarget,button=form.querySelector('[type=submit]');const texts={...data.content.texts},textsEn={...data.content.textsEn};form.querySelectorAll('[data-text-key]').forEach(field=>texts[field.dataset.textKey]=field.value.trim());form.querySelectorAll('[data-english-key]').forEach(field=>textsEn[field.dataset.englishKey]=field.value.trim());button.disabled=true;$('#content-error').textContent='';try{await api('content',{method:'PUT',body:{content:{...data.content,texts,textsEn}}});await refresh();toast('Tulisan undangan diperbarui untuk semua tamu.');}catch(error){$('#content-error').textContent=error.message;}finally{button.disabled=false;}});
$('#cms-photo-fields').addEventListener('change',async e=>{const input=e.target;if(input.type!=='file'||!input.files?.length)return;const file=input.files[0],card=input.closest('[data-photo-id]'),id=Number(card.dataset.photoId),status=card.querySelector('.upload-status');if(file.size>8000000){status.textContent='Foto maksimal 8 MB.';input.value='';return;}input.disabled=true;status.textContent='Mengunggah foto…';try{const result=await window.uploadWeddingFile(file,{kind:'photo'});data.content.photos[id-1].src=result.src;card.querySelector('img').src=result.src;$('#cms-featured-fields').querySelectorAll('select').forEach(select=>{if(Number(select.value)===id){const preview=select.parentElement.querySelector('img');preview.src=result.src;preview.alt=data.content.photos[id-1].alt;}});status.textContent='Foto diunggah. Tekan “Simpan foto & galeri” untuk menerbitkan.';}catch(error){status.textContent=error.message;}finally{input.disabled=false;input.value='';}});
$('#photos-form').addEventListener('submit',async e=>{e.preventDefault();const form=e.currentTarget,button=form.querySelector('[type=submit]');const photos=data.content.photos.map(p=>{const card=form.querySelector(`[data-photo-id="${p.id}"]`),value=name=>card.querySelector(`[data-photo-field="${name}"]`).value.trim();return {...p,caption:value('caption'),captionEn:value('captionEn'),alt:value('alt'),altEn:value('altEn'),category:value('category')};});const selects=[...$('#cms-featured-fields').querySelectorAll('select')].map(el=>Number(el.value));const featured={hero:selects.slice(0,3),couple:selects[3],closing:selects[4]};button.disabled=true;$('#photos-error').textContent='';try{await api('content',{method:'PUT',body:{content:{...data.content,photos,featured}}});await refresh();toast('Foto dan galeri diperbarui untuk semua tamu.');}catch(error){$('#photos-error').textContent=error.message;}finally{button.disabled=false;}});
if(['localhost','127.0.0.1'].includes(location.hostname))$('#local-note').hidden=false;
(async()=>{try{const session=await api('session');$('#admin-email').textContent=session.email;await refresh();}catch(error){$('#loading').hidden=true;topError(error);}})();
// Optional agent tools use the same authenticated API and visible UI actions.
if(document.modelContext?.registerTool){const lifecycle=new AbortController();const tools=[{name:'list_wedding_invitations',title:'Lihat daftar undangan',description:'Read the invitations visible to the signed-in wedding administrator. Does not send or change invitations.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute:async input=>{if(!input||Object.keys(input).length)throw new Error('No input fields supported');await refresh();return {invitations:data.invitations.map(i=>({name:i.guestName,slug:i.slug,opened:Boolean(i.firstOpenedAt),active:i.active})),responses:data.responses.map(r=>({invitationId:r.invitation_id,eventId:r.event_id,status:r.status,guestCount:r.guest_count}))};}},{name:'start_wedding_invitation',title:'Siapkan undangan baru',description:'Open and prefill the new invitation form. Does not create or send an invitation; administrator must submit the form.',inputSchema:{type:'object',properties:{guestName:{type:'string',maxLength:100}},required:['guestName'],additionalProperties:false},annotations:{readOnlyHint:false},execute:async input=>{if(typeof input?.guestName!=='string'||!input.guestName.trim()||input.guestName.length>100||Object.keys(input).some(k=>k!=='guestName'))throw new Error('Provide a guestName from 1 to 100 characters');openInvitation();$('#guest-name-input').value=input.guestName;$('#slug-input').value=slugify(input.guestName);return {formOpen:true,guestName:input.guestName,slug:$('#slug-input').value,created:false};}}];for(const tool of tools){try{Promise.resolve(document.modelContext.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{});}catch{}}window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});}

// CSV import keeps each row linked to a private, shareable invitation URL.
let bulkRows=[],bulkCreated=[];
const csvEscape=value=>'"'+String(value??'').replaceAll('"','""')+'"';
function downloadCsv(filename,rows){const blob=new Blob(['\uFEFF'+rows.map(row=>row.map(csvEscape).join(',')).join('\r\n')+'\r\n'],{type:'text/csv;charset=utf-8'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=filename;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
const readBulkCsv=source=>window.weddingBulkCsv.read(source);
$('#bulk-invitation').addEventListener('click',()=>{bulkRows=[];bulkCreated=[];$('#bulk-form').hidden=false;$('#bulk-result').hidden=true;$('#bulk-file').value='';$('#bulk-preview').textContent='Belum ada berkas dipilih.';$('#bulk-error').textContent='';$('#bulk-dialog').showModal();});
$('#bulk-template').addEventListener('click',event=>{event.preventDefault();downloadCsv('template-tamu.csv',window.weddingBulkCsv.template);});
$('#bulk-file').addEventListener('change',async event=>{bulkRows=[];$('#bulk-error').textContent='';const file=event.target.files?.[0];if(!file)return;try{if(file.size>20000)throw new Error('Berkas CSV maksimal 20 KB.');bulkRows=readBulkCsv(await file.text());const totals=new Map();for(const row of bulkRows)if(row.receptionTable)totals.set(row.receptionTable,(totals.get(row.receptionTable)||0)+row.seats);const warnings=[...totals].filter(([table,seats])=>reservedAt(table)+seats>TABLE_CAPACITY).map(([table])=>table);$('#bulk-preview').textContent=`${bulkRows.length} undangan · ${bulkRows.reduce((total,row)=>total+row.seats,0)} orang siap diunggah.${warnings.length?' Meja melebihi 10 kursi: '+warnings.join(', ')+'. Perbaiki CSV terlebih dahulu.':''}`;if(warnings.length)throw new Error('Ada meja yang melebihi kapasitas 10 kursi.');}catch(error){bulkRows=[];$('#bulk-preview').textContent='Berkas belum siap diunggah.';$('#bulk-error').textContent=error.message;}});
$('#bulk-form').addEventListener('submit',async event=>{event.preventDefault();if(!bulkRows.length){$('#bulk-error').textContent='Pilih berkas CSV yang valid dahulu.';return;}const button=$('#bulk-submit');button.disabled=true;$('#bulk-error').textContent='';try{const result=await api('invitations/bulk',{method:'POST',body:{invitations:bulkRows}});bulkCreated=result.created;$('#bulk-form').hidden=true;$('#bulk-result').hidden=false;$('#bulk-result').querySelector('p').textContent=`${bulkCreated.length} undangan berhasil dibuat. Unduh daftar tautan personal untuk dibagikan.`;showAllGuests();await refresh();toast(`${bulkCreated.length} undangan dibuat.`);}catch(error){$('#bulk-error').textContent=error.message;}finally{button.disabled=false;}});
$('#bulk-download').addEventListener('click',()=>downloadCsv('tautan-undangan.csv',[['nama','slug','tautan'],...bulkCreated.map(item=>[item.guestName,item.slug,location.origin+item.sharePath])]));

let messagesPage=1,messagesHasMore=false,messagesLoading=false,generalPage=1,generalHasMore=false;
async function loadMessages(next=1){
 if(messagesLoading)return;messagesLoading=true;$('#message-admin-error').textContent='';
 try{const result=await api('messages?page='+next+'&status='+encodeURIComponent($('#message-filter').value));messagesPage=result.page;messagesHasMore=result.hasMore;$('#message-service-status').textContent=result.translationConfigured?'Terjemahan dan penyaringan otomatis aktif. Pesan asli selalu dipertahankan.':'Layanan bahasa belum terhubung. Pesan baru hanya terlihat oleh pengirim sampai ditinjau admin.';
 $('#admin-messages').innerHTML=result.messages.length?result.messages.map(m=>`<article class="admin-message"><header><strong>${esc(m.guest_name)}</strong>${badge({published:'Tampil untuk semua',pending:'Perlu ditinjau',held:'Disembunyikan'}[m.status],m.status==='published'?'good':m.status==='pending'?'warm':'bad')}</header><small>${esc(when(m.created_at))} · ${m.invitation_id?'Undangan personal':'Undangan umum'} · ${esc(m.language)}</small><h3>Pesan asli</h3><p dir="auto">${esc(m.original)}</p>${m.translation_id?`<details><summary>Terjemahan Indonesia</summary><p>${esc(m.translation_id)}</p></details>`:''}${m.translation_en?`<details><summary>English translation</summary><p>${esc(m.translation_en)}</p></details>`:''}<div class="row-actions"><button class="quiet" data-message-id="${m.id}" data-message-status="${m.status==='published'?'held':'published'}">${m.status==='published'?'Sembunyikan':'Tampilkan untuk semua'}</button><button class="quiet" data-message-id="${m.id}" data-message-translate="true">Periksa & terjemahkan ulang</button></div></article>`).join(''):'<p class="empty">Belum ada pesan pada filter ini.</p>';
 $('#messages-page-label').textContent='Halaman '+messagesPage+' · maksimal 20 pesan';$('#messages-prev').disabled=messagesPage<=1;$('#messages-next').disabled=!messagesHasMore;
 }catch(error){$('#message-admin-error').textContent=error.message;}finally{messagesLoading=false;}
}
$('#message-filter').addEventListener('change',()=>loadMessages(1));$('#messages-refresh').addEventListener('click',()=>loadMessages(messagesPage));$('#messages-prev').addEventListener('click',()=>loadMessages(messagesPage-1));$('#messages-next').addEventListener('click',()=>loadMessages(messagesPage+1));
$('#admin-messages').addEventListener('click',async event=>{const button=event.target.closest('[data-message-id]');if(!button)return;button.disabled=true;try{if(button.dataset.messageTranslate){const result=await api('messages/'+button.dataset.messageId+'/translate',{method:'POST',body:{}});toast(result.translated?'Pesan sudah diperiksa dan diterjemahkan.':'Terjemahan belum tersedia. Pesan asli tetap tersimpan.');}else await api('messages/'+button.dataset.messageId,{method:'PATCH',body:{status:button.dataset.messageStatus}});await loadMessages(messagesPage);}catch(error){$('#message-admin-error').textContent=error.message;button.disabled=false;}});
async function loadGeneralRsvps(next=1){$('#general-error').textContent='';try{const result=await api('general-rsvps?page='+next);generalPage=result.page;generalHasMore=result.hasMore;$('#general-rsvps').innerHTML=result.rsvps.length?result.rsvps.map(r=>`<article class="admin-message"><header><strong>${esc(r.name)}</strong><small>${esc(when(r.updatedAt))}</small></header>${r.responses.map(response=>`<div class="detail-stat"><span>${esc(data.events.find(e=>e.id===response.event_id)?.title||response.event_id)}</span>${rsvpMarkup(response)}</div>`).join('')}</article>`).join(''):'<p class="empty">Belum ada jawaban dari undangan umum.</p>';$('#general-page-label').textContent='Halaman '+generalPage;$('#general-prev').disabled=generalPage<=1;$('#general-next').disabled=!generalHasMore;}catch(error){$('#general-error').textContent=error.message;}}
$('#general-refresh').addEventListener('click',()=>loadGeneralRsvps(generalPage));$('#general-prev').addEventListener('click',()=>loadGeneralRsvps(generalPage-1));$('#general-next').addEventListener('click',()=>loadGeneralRsvps(generalPage+1));

// Gift interactions stay separate from verified gifts and include public visitors.
let giftActivityPage=1,giftActivityLoading=false;
async function loadGiftActivity(target=1){
 if(giftActivityLoading)return;giftActivityLoading=true;
 $('#gift-activity-error').textContent='';$('#gift-activity-refresh').disabled=true;
 $('#gift-activity-prev').disabled=true;$('#gift-activity-next').disabled=true;
 try{
  const result=await api('gift-activity?page='+target);giftActivityPage=result.page;
  $('#gift-activity-rows').innerHTML=result.activity.length?result.activity.map(a=>{
   const name=a.invitation_name?displayName({guestName:a.invitation_name,salutation:a.salutation}):a.general_name||'Pengunjung tanpa nama';
   return `<tr><td><strong>${esc(name)}</strong><small>${a.slug?'/'+esc(a.slug):'Undangan umum · '+esc(a.visitorLabel)}</small></td><td>${Number(a.opened)||0}</td><td>${Number(a.copy_clicked)||0}</td><td>${Number(a.account_copied)||0}</td><td>${esc(when(a.last_activity_at))}</td></tr>`;
  }).join(''):'<tr><td colspan="5" class="empty"><strong>Belum ada aktivitas hadiah.</strong>Klik tamu akan tercatat di sini. Pratinjau admin tidak dihitung.</td></tr>';
  $('#gift-activity-page').textContent='Halaman '+result.page;
  $('#gift-activity-prev').disabled=result.page===1;$('#gift-activity-next').disabled=!result.hasMore;
 }catch(error){$('#gift-activity-error').textContent=error.message;}
 finally{giftActivityLoading=false;$('#gift-activity-refresh').disabled=false;}
}
$('#gift-activity-refresh').addEventListener('click',()=>loadGiftActivity(giftActivityPage));
$('#gift-activity-prev').addEventListener('click',()=>loadGiftActivity(giftActivityPage-1));
$('#gift-activity-next').addEventListener('click',()=>loadGiftActivity(giftActivityPage+1));

let readingPage=1,readingLoading=false;
async function loadReading(target=1){
 if(readingLoading)return;readingLoading=true;$('#reading-error').textContent='';$('#reading-refresh').disabled=true;$('#reading-prev').disabled=true;$('#reading-next').disabled=true;
 try{
  const result=await api('reading-progress?page='+target),summary=result.summary,total=Number(summary.readers)||0;readingPage=result.page;
  $('#reading-readers').textContent=total;$('#reading-visits').textContent=Number(summary.visits)||0;$('#reading-depth').textContent=Math.round(Number(summary.average_depth)||0)+'%';$('#reading-finished').textContent=Number(summary.finished)||0;
  const chart=kind=>result.sections.map((section,index)=>{const count=Number(summary[kind+'_'+index])||0,percent=total?Math.round(count/total*100):0;return `<div class="reading-bar"><div><span>${esc(section.label)}</span><strong>${count} · ${percent}%</strong></div><div class="reading-track" role="meter" aria-label="${esc(section.label)}" aria-valuemin="0" aria-valuemax="${Math.max(1,total)}" aria-valuenow="${count}"><span style="width:${percent}%"></span></div></div>`;}).join('');
  $('#reading-hot').innerHTML=chart('reach');$('#reading-stops').innerHTML=chart('stop');
  const leaders=kind=>{const counts=result.sections.map((section,index)=>Number(summary[kind+'_'+index])||0),max=Math.max(...counts);return max?result.sections.filter((section,index)=>counts[index]===max).map(section=>section.label).join(' / ')+' · '+max:'Belum ada data';};
  $('#reading-hot-label').textContent='Paling banyak dijangkau: '+leaders('reach');$('#reading-stop-label').textContent='Paling banyak sampai di: '+leaders('stop');
  $('#reading-rows').innerHTML=result.readers.length?result.readers.map(r=>{const name=r.invitation_name?displayName({guestName:r.invitation_name,salutation:r.salutation}):r.general_name||'Pengunjung tanpa nama';return `<tr><td><strong>${esc(name)}</strong><small>${r.slug?'/'+esc(r.slug):'Undangan umum · '+esc(r.visitorLabel)}</small></td><td>${Number(r.max_depth)}%</td><td>${esc(result.sections[r.deepest_section]?.label)}</td><td>${esc(result.sections[r.last_section]?.label)}</td><td>${Number(r.visits)}</td><td>${esc(when(r.last_seen))}</td></tr>`;}).join(''):'<tr><td colspan="6" class="empty"><strong>Belum ada data scroll.</strong>Data muncul setelah tamu membuka undangan dan mulai melihat section.</td></tr>';
  $('#reading-page-label').textContent='Halaman '+result.page;$('#reading-prev').disabled=result.page===1;$('#reading-next').disabled=!result.hasMore;
 }catch(error){$('#reading-error').textContent=error.message;}finally{readingLoading=false;$('#reading-refresh').disabled=false;}
}
$('#reading-refresh').addEventListener('click',()=>loadReading(readingPage));$('#reading-prev').addEventListener('click',()=>loadReading(readingPage-1));$('#reading-next').addEventListener('click',()=>loadReading(readingPage+1));
